        { id: "cd12", title: "最后一攻", scene: "平局，三秒。对面最后一攻冲击篮下——你是最后一道防线。", choices: [{ label: "垂直护框", base: 0.56, key: "BLK" }, { label: "站定", base: 0.44, key: "CLU", hit: "你站定，他撞进你怀里——进攻犯规！球权回来！", miss: "你站定，他造到犯规——两罚。" }, { label: "贴身", base: 0.4, key: "PDEF", hit: "你贴身，他仓促出手——打铁！", miss: "你贴身，他换手上篮命中。" }], hit: "你垂直护框，他上篮被帽——进加时。", miss: "你贴身，他造犯规——两罚。" },
        { id: "cd13", title: "顶住低位", scene: "领先一分，七秒。对面中锋低位拿球——他今晚已经用同一个转身跳投吃了你两次，你听到教练在喊你的名字。", choices: [{ label: "预判转身方向", base: 0.52, key: "PDEF" }, { label: "绕前防接球", base: 0.44, key: "HAN", hit: "你绕前防接球，他接不到——传球失误！", miss: "你绕前，他反跑接球——转身命中。" }, { label: "上身体顶防", base: 0.4, key: "STR", hit: "你上身体顶防，他强转——被顶住打铁！", miss: "你上身体，他顺势转身——过掉你。" }], hit: "他转身起跳，你提前一步贴住——干扰成功，打铁。", miss: "你预判转身，他这球换了假动作——中投命中。" }
