        { id: "cpd02", title: "附加赛的造进攻犯规", scene: "附加赛，平局，四秒。对面后卫全速冲击篮下——他一路没刹车。", choices: [{ label: "提前站定", base: 0.54, key: "CLU", hit: "你提前站定，他撞进你怀里——进攻犯规！球权回来！", miss: "你提前站定，他跳步躲开——上篮命中。" }, { label: "起跳封盖", base: 0.42, key: "BLK", hit: "你起跳封盖——大帽！", miss: "你起跳封盖，他造犯规——两罚。" }, { label: "让开", base: 0.4, key: "ATH", hit: "你让开，他撞上协防——失误！", miss: "你让开，他轻松上篮命中。" }], hit: "你提前站定，他撞进你怀里——进攻犯规！球权回来！", miss: "你提前站定，他跳步躲开——上篮命中。" },
        { id: "cpd03", title: "附加赛的篮板", scene: "附加赛，落后一分，五秒。对面最后一投——球弹得高，你在篮下。", choices: [{ label: "卡位抢板", base: 0.56, key: "REB", hit: "你卡位抢板——收下篮板，时间走完，进加时！", miss: "你卡位抢板，被拨走——补进。" }, { label: "跳起干扰", base: 0.42, key: "BLK", hit: "你跳起干扰，球弹飞——卡位收下，进加时！", miss: "你跳起干扰，被补进。" }, { label: "点给队友", base: 0.4, key: "PAS", hit: "你点给队友——他接住球，时间走完，进加时！", miss: "你点给队友，被抢断——补进。" }], hit: "你卡位抢板——收下篮板，时间走完，进加时！", miss: "你卡位抢板，被拨走——补进。" },
        { id: "cpd04", title: "附加赛的防空接", scene: "附加赛，平局，四秒。对面打空接战术——他们的中锋已经往篮下冲。", choices: [{ label: "卡住路线", base: 0.54, key: "STR", hit: "你卡住路线，他接不到球——失误，球权到手！", miss: "你卡路线，被撞开——空接扣进。" }, { label: "盯持球人", base: 0.42, key: "PDEF", hit: "你盯持球人，他犹豫——传球失误！", miss: "你盯持球人，他高抛——空接扣进。" }, { label: "跳起干扰", base: 0.4, key: "BLK", hit: "你跳起干扰——拍掉传球！", miss: "你跳起干扰，球被接住——扣进。" }], hit: "你卡住路线，他接不到球——失误，球权到手！", miss: "你卡路线，被撞开——空接扣进。" },
        { id: "cpd05", title: "附加赛的防勾手", scene: "附加赛，落后一分，三秒。对面中锋要勾手——他右手准，左手一般。", choices: [{ label: "逼他左手", base: 0.54, key: "PDEF", hit: "你逼他左手，他勾手——打铁，附加赛拿下！", miss: "你逼他左手，他右手勾手命中——赛季结束。" }, { label: "正常封盖", base: 0.44, key: "BLK", hit: "你正常封盖——大帽！", miss: "你起跳封盖，他造犯规——两罚。" }, { label: "贴身", base: 0.4, key: "STR", hit: "你贴身，他勾手被干扰——打铁！", miss: "你贴身，他转身勾手命中。" }], hit: "你逼他左手，他勾手——打铁，附加赛拿下！", miss: "你逼他左手，他右手勾手命中——赛季结束。" },
        { id: "cpd06", title: "附加赛的最后一攻", scene: "附加赛，平局，三秒。对面最后一攻冲击篮下——你是最后一道防线。", choices: [{ label: "垂直护框", base: 0.54, key: "BLK", hit: "你垂直护框——他上篮被帽，进加时！", miss: "你垂直护框，他造犯规——两罚，赛季结束。" }, { label: "站定", base: 0.44, key: "CLU", hit: "你站定，他撞进你怀里——进攻犯规！球权回来！", miss: "你站定，他造到犯规——两罚。" }, { label: "贴身", base: 0.4, key: "PDEF", hit: "你贴身，他仓促出手——打铁！", miss: "你贴身，他换手上篮命中。" }], hit: "你垂直护框——他上篮被帽，进加时！", miss: "你垂直护框，他造犯规——两罚，赛季结束。" }
