        { id: "pgd20", gameTag: "g1_4", title: "系列赛的首战盯防", scene: "系列赛第一场，领先一分，六秒。对面控卫要打最后一攻——你整场研究过他的习惯。", choices: [{ label: "逼他走左手", base: 0.54, key: "PDEF", hit: "你逼他走左手，他仓促出手——打铁，拿下首战！", miss: "你逼左手，他强突命中。" }, { label: "预判突破抢断", base: 0.44, key: "HAN", hit: "你预判突破，掏走球——比赛结束！", miss: "你预判突破，他干拔命中。" }, { label: "放他中投", base: 0.38, key: "CLU", hit: "你放他中投，他手感冰凉——打铁！", miss: "你放他中投，他命中。" }], hit: "你逼他走左手，他仓促出手——打铁，拿下首战！", miss: "你逼左手，他强突命中。" },
        { id: "pgd21", gameTag: "g1_4", title: "客场的压力", scene: "系列赛客场，平局，五秒。全场球迷嘘你，对面控卫自信地运球——他今晚突破比投篮多。", choices: [{ label: "放突不放投", base: 0.54, key: "PDEF", hit: "你放突不放投，他强突被顶住——打铁，客场拿下！", miss: "你放突，他上篮命中。" }, { label: "贴身紧逼", base: 0.44, key: "ATH", hit: "你贴身紧逼，他慌乱出球——失误！", miss: "你贴身，他一步过掉。" }, { label: "包夹逼出球", base: 0.4, key: "CLU", hit: "你招呼包夹，他仓促传球——被断！", miss: "你包夹，他找到空位。" }], hit: "你放突不放投，他强突被顶住——打铁，客场拿下！", miss: "你放突，他上篮命中。" },
        { id: "pgd22", gameTag: "g1_4", title: "系列赛的调整", scene: "系列赛，落后一分，四秒。对面控卫叫了挡拆——他们的中锋挡人结实，但顺下一般。", choices: [{ label: "挤过掩护贴死", base: 0.54, key: "PDEF", hit: "你挤过掩护贴死，他急停出手——打铁！", miss: "你挤过掩护，被他过掉——上篮命中。" }, { label: "换防", base: 0.42, key: "ATH", hit: "你换防，中锋没接住球——失误！", miss: "你换防，被他变向过掉。" }, { label: "绕掩护赌三分", base: 0.38, key: "CLU", hit: "你绕掩护，他拔起三分——打铁！", miss: "你绕掩护，他三分命中。" }], hit: "你挤过掩护贴死，他急停出手——打铁！", miss: "你挤过掩护，被他过掉——上篮命中。" },
        { id: "pgd23", gameTag: "g1_4", title: "系列赛的抢断", scene: "系列赛，平局，六秒。对面控卫紧张时爱低头看球——他已经失误 5 次。", choices: [{ label: "赌他低头掏球", base: 0.5, key: "HAN", hit: "他低头那一下，你掏走球——反击绝杀！", miss: "你赌他低头，他这次没看——过掉你命中。" }, { label: "保守跟防", base: 0.46, key: "PDEF", hit: "你保守跟防，他急停被干扰——打铁！", miss: "你保守跟防，他突破上进。" }, { label: "招呼包夹", base: 0.4, key: "CLU", hit: "你招呼包夹，他慌乱出球——被断！", miss: "你招呼包夹，他找到空位。" }], hit: "他低头那一下，你掏走球——反击绝杀！", miss: "你赌他低头，他这次没看——过掉你命中。" },
        { id: "pgd24", gameTag: "g1_4", title: "系列赛的造犯规", scene: "系列赛，平局，五秒。对面控卫全速冲击篮下——他一路没刹车的习惯。", choices: [{ label: "提前站定", base: 0.54, key: "CLU", hit: "你提前站定，他撞进你怀里——进攻犯规！球权回来！", miss: "你提前站定，他跳步躲开——上篮命中。" }, { label: "正面防守", base: 0.42, key: "PDEF", hit: "你正面防守，他急停被干扰——打铁！", miss: "你正面防守，他强突上进。" }, { label: "侧身闪开", base: 0.38, key: "ATH", hit: "你侧身闪开，他撞上协防——失误！", miss: "你侧身闪开，他轻松上篮。" }], hit: "你提前站定，他撞进你怀里——进攻犯规！球权回来！", miss: "你提前站定，他跳步躲开——上篮命中。" },
        { id: "pgd25", gameTag: "g1_4", title: "系列赛的贴防", scene: "系列赛，领先一分，七秒。对面控卫最后一攻，全场让路——但他今晚助攻 12 个，传球同样危险。", choices: [{ label: "贴身不失位", base: 0.52, key: "PDEF", hit: "你贴身不失位，他强投——打铁，拿下！", miss: "你贴身，他一步过掉。" }, { label: "盯传球路线", base: 0.44, key: "HAN", hit: "你盯传球路线，他出球被断——比赛结束！", miss: "你盯传球，他自己攻——命中。" }, { label: "放一步防突破", base: 0.4, key: "CLU", hit: "你放一步防突破，他拔起——打铁！", miss: "你放一步，他干拔命中。" }], hit: "你贴身不失位，他强投——打铁，拿下！", miss: "你贴身，他一步过掉。" },
        { id: "pgd26", gameTag: "g5", title: "天王山的防守", scene: "天王山，领先一分，九秒。对面控卫整轮都在借掩护找错位——他第三节已经打成你两次。", choices: [{ label: "挤过掩护贴死", base: 0.54, key: "PDEF", hit: "你挤过掩护贴死，他仓促出手——打铁，天王山拿下！", miss: "你挤过掩护，被他甩开——命中。" }, { label: "换防后紧跟", base: 0.42, key: "ATH", hit: "你换防后紧跟，他急停出手——打铁！", miss: "你换防，被他变向过掉。" }, { label: "放一步赌他三分", base: 0.38, key: "CLU", hit: "你放一步赌他三分，他拔起——打铁！", miss: "你放一步，他三分命中。" }], hit: "你挤过掩护贴死，他仓促出手——打铁，天王山拿下！", miss: "你挤过掩护，被他甩开——命中。" },
        { id: "pgd27", gameTag: "g5", title: "天王山的紧逼", scene: "天王山，平局，六秒。对面控卫打了 40 分钟，已经明显喘了——他第四节 3 投 0 中。", choices: [{ label: "贴身施压", base: 0.54, key: "PDEF", hit: "你贴身施压，他勉强出手——打铁，天王山拿下！", miss: "你贴身施压，他后撤步命中。" }, { label: "赌他传球", base: 0.42, key: "HAN", hit: "你赌他传球，断下——比赛结束！", miss: "你赌传球，他强投命中。" }, { label: "放他中投", base: 0.4, key: "CLU", hit: "你放他中投，他体力不支——打铁！", miss: "你放他中投，他命中。" }], hit: "你贴身施压，他勉强出手——打铁，天王山拿下！", miss: "你贴身施压，他后撤步命中。" },
        { id: "pgd28", gameTag: "g6w", title: "系列赛的终结防守", scene: "系列赛 3-2 领先，第六场，领先一分，八秒。对面控卫必须得分——他压住了节奏。", choices: [{ label: "贴身防投篮", base: 0.52, key: "PDEF", hit: "你贴身防投，他仓促出手——打铁，终结系列赛！", miss: "你贴身，他后撤步命中——被拖进抢七。" }, { label: "预判突破", base: 0.44, key: "HAN", hit: "你预判突破，堵住路线——他失误，终结系列赛！", miss: "你预判突破，他干拔命中。" }, { label: "放一步赌手感", base: 0.4, key: "CLU", hit: "你放一步赌他手感，他拔起——打铁，终结系列赛！", miss: "你放一步，他干拔命中。" }], hit: "你贴身防投，他仓促出手——打铁，终结系列赛！", miss: "你贴身，他后撤步命中——被拖进抢七。" },
        { id: "pgd29", gameTag: "g6s", title: "追平系列赛的防守", scene: "系列赛 2-3 落后，第六场，平局，四秒。对面控卫要打最后一攻——他今晚手感火热。", choices: [{ label: "贴身干扰", base: 0.52, key: "PDEF", hit: "你贴身干扰，他强投——打铁，拖进抢七！", miss: "你贴身，他后撤步命中——赛季结束。" }, { label: "预判突破掏球", base: 0.44, key: "HAN", hit: "你预判突破掏球——断下，拖进抢七！", miss: "你掏球，他干拔命中。" }, { label: "放他中投", base: 0.4, key: "CLU", hit: "你放他中投，他手感骤冷——打铁！", miss: "你放他中投，他命中。" }], hit: "你贴身干扰，他强投——打铁，拖进抢七！", miss: "你贴身，他后撤步命中——赛季结束。" },
        { id: "pgd30", gameTag: "any", title: "系列赛的最后一防", scene: "系列赛，平局，三秒。对面控卫最后一攻——你今晚防他效率极低。", choices: [{ label: "全力盯防", base: 0.52, key: "PDEF", hit: "你全力盯防，他强投——打铁，拿下！", miss: "你全力盯防，他后仰命中。" }, { label: "放一步", base: 0.44, key: "CLU", hit: "你放一步，他拔起——打铁！", miss: "你放一步，他干拔命中。" }, { label: "协防埋伏", base: 0.4, key: "HAN", hit: "你协防埋伏，他出球被断——比赛结束！", miss: "你协防埋伏，他单打命中。" }], hit: "你全力盯防，他强投——打铁，拿下！", miss: "你全力盯防，他后仰命中。" }
