        { id: "pf21", gameTag: "g1_4", title: "系列赛的低位", scene: "系列赛第一场，低位拿球，四秒。对手用身体顶着你——他重心压得很低。", choices: [{ label: "转身跳投", base: 0.52, key: "MID", hit: "你转身跳投——命中，拿下首战！", miss: "你转身跳投，被干扰——打铁。" }, { label: "梦幻脚步", base: 0.44, key: "FIN", hit: "你梦幻脚步——晃开他上篮命中，拿下首战！", miss: "你梦幻脚步，被识破——球被切。" }, { label: "勾手", base: 0.4, key: "FIN", hit: "你勾手——命中，拿下首战！", miss: "你勾手，弹框。" }], hit: "你转身跳投——命中，拿下首战！", miss: "你转身跳投，被干扰——打铁。" },
        { id: "pf22", gameTag: "g1_4", title: "系列赛的篮板", scene: "系列赛，落后两分，五秒。队友三分偏出，球弹向你——你面前是对面最好的篮板手。", choices: [{ label: "补扣", base: 0.5, key: "DNK", hit: "你补扣——命中，追平进加时！", miss: "你补扣，被卡住——球飞了。" }, { label: "双手补篮", base: 0.46, key: "FIN", hit: "你双手补篮——球进，追平进加时！", miss: "你补篮，被顶住。" }, { label: "卡位后勾手", base: 0.4, key: "STR", hit: "你卡位后勾手——命中，追平进加时！", miss: "你勾手，被干扰。" }], hit: "你补扣——命中，追平进加时！", miss: "你补扣，被卡住——球飞了。" },
        { id: "pf23", gameTag: "g1_4", title: "系列赛的挡拆", scene: "系列赛，平局，五秒。你提上掩护，对面换防——你面对他们的控卫。", choices: [{ label: "顺下吃小个", base: 0.54, key: "STR", hit: "你顺下吃小个——顶开他放进，拿下！", miss: "你顺下，被协防帽掉。" }, { label: "外弹三分", base: 0.42, key: "threePT", hit: "你外弹三分——命中，拿下！", miss: "你外弹三分，打铁。" }, { label: "分球弱侧", base: 0.4, key: "PAS", hit: "你吸引包夹分球弱侧——队友命中，拿下！", miss: "你分球被断。" }], hit: "你顺下吃小个——顶开他放进，拿下！", miss: "你顺下，被协防帽掉。" },
        { id: "pf24", gameTag: "g1_4", title: "系列赛的强攻", scene: "系列赛，落后一分，四秒。对面中锋已经五犯，他不敢再跳——这是信号。", choices: [{ label: "强起造犯规", base: 0.52, key: "STR", hit: "你强起造犯规——两罚命中，拿下！", miss: "你强起，他赌你出手——帽掉。" }, { label: "勾手", base: 0.46, key: "FIN", hit: "你勾手——命中，拿下！", miss: "你勾手，被干扰。" }, { label: "转身跳投", base: 0.4, key: "MID", hit: "你转身跳投——命中，拿下！", miss: "你转身跳投，弹框。" }], hit: "你强起造犯规——两罚命中，拿下！", miss: "你强起，他赌你出手——帽掉。" },
        { id: "pf25", gameTag: "g1_4", title: "系列赛的错位", scene: "系列赛，落后两分，六秒。对面换防，你面前是他们的小前锋——比你矮比你慢。", choices: [{ label: "低位强吃", base: 0.54, key: "STR", hit: "你低位强吃——顶开他放进，拿下！", miss: "你低位强吃，被协防切掉。" }, { label: "面框跳投", base: 0.42, key: "MID", hit: "你面框跳投——命中，拿下！", miss: "你面框跳投，被干扰。" }, { label: "背打后分球", base: 0.4, key: "PAS", hit: "你背打吸引包夹分球——队友命中，拿下！", miss: "你分球被切。" }], hit: "你低位强吃——顶开他放进，拿下！", miss: "你低位强吃，被协防切掉。" },
        { id: "pf26", gameTag: "g1_4", title: "系列赛的罚球线", scene: "系列赛，平局，四秒。你在罚球线拿到球，对面中锋蹲坑不出来——他把中距离让给你。", choices: [{ label: "中距离", base: 0.56, key: "MID", hit: "你罚球线中距离——空心命中，拿下！", miss: "你中距离，弹框。" }, { label: "突破暴扣", base: 0.42, key: "DNK", hit: "你突破暴扣——命中，拿下！", miss: "你突破暴扣，被帽。" }, { label: "传给空切", base: 0.4, key: "PAS", hit: "你传给空切队友——他上篮命中，拿下！", miss: "你传球被断。" }], hit: "你罚球线中距离——空心命中，拿下！", miss: "你中距离，弹框。" },
        { id: "pf27", gameTag: "g5", title: "天王山的低位", scene: "天王山，平局，五秒。对面收缩内线，你低位拿球——正面有一小块空档。", choices: [{ label: "转身中投", base: 0.54, key: "MID", hit: "你转身中投——命中，天王山拿下！", miss: "你转身中投，弹框。" }, { label: "分球外线", base: 0.42, key: "PAS", hit: "你吸引包夹分球外线——队友三分命中，天王山拿下！", miss: "你分球被断。" }, { label: "强打", base: 0.4, key: "STR", hit: "你强打——顶开防守放进，天王山拿下！", miss: "你强打，双人协防——球被切。" }], hit: "你转身中投——命中，天王山拿下！", miss: "你转身中投，弹框。" },
        { id: "pf28", gameTag: "g5", title: "天王山的得分", scene: "天王山，落后两分，五秒。对面换上一个机动型内线防你——他比你快，但对抗吃亏。", choices: [{ label: "强推一步转身", base: 0.54, key: "FIN", hit: "你强推一步转身——上篮命中，天王山拿下！", miss: "你强推转身，被协防帽掉。" }, { label: "翻身跳投", base: 0.44, key: "MID", hit: "你翻身跳投——命中，天王山拿下！", miss: "你翻身跳投，弹框。" }, { label: "吸引夹击传底角", base: 0.38, key: "PAS", hit: "你吸引夹击传底角——队友命中，天王山拿下！", miss: "你传球被断。" }], hit: "你强推一步转身——上篮命中，天王山拿下！", miss: "你强推转身，被协防帽掉。" },
        { id: "pf29", gameTag: "g6w", title: "系列赛的终结", scene: "系列赛 3-2 领先，第六场，领先一分，八秒。对面必须得分——你持球稳住。", choices: [{ label: "护球造犯规", base: 0.52, key: "CLU", hit: "你护球造犯规——两罚命中，终结系列赛！", miss: "你护球，被抢断——被拖进抢七。" }, { label: "强打内线", base: 0.44, key: "FIN", hit: "你强打内线——放进，终结系列赛！", miss: "你强打，被帽。" }, { label: "传空位队友", base: 0.4, key: "PAS", hit: "你传空位队友——他命中，终结系列赛！", miss: "你传球被断。" }], hit: "你护球造犯规——两罚命中，终结系列赛！", miss: "你护球，被抢断——被拖进抢七。" },
        { id: "pf30", gameTag: "any", title: "系列赛的关键球", scene: "系列赛，平局，四秒。低位拿球，对面防守人贴得很近——他以为你要强打。", choices: [{ label: "金鸡独立", base: 0.54, key: "MID", hit: "你金鸡独立——中投命中，拿下！", miss: "你金鸡独立，被干扰——打铁。" }, { label: "转身勾手", base: 0.44, key: "FIN", hit: "你转身勾手——命中，拿下！", miss: "你转身勾手，弹框。" }, { label: "传外线", base: 0.4, key: "PAS", hit: "你吸引包夹传外线——队友三分命中，拿下！", miss: "你传球被断。" }], hit: "你金鸡独立——中投命中，拿下！", miss: "你金鸡独立，被干扰——打铁。" }
