// ============================================================
// 关键时刻核心逻辑（纯函数，便于引擎与测试复用）
// ============================================================

// 关键时刻专用属性系数：高段更陡，99 OVR 时约 1.08（满级有溢出加成，让高 OVR 期望更高）
// 25→0.20  60→0.45  75→0.64  85→0.80  90→0.88  95→0.97  99→1.08
CLUTCH_EVENTS.hitAF = function (val) {
  var v = Math.max(25, Math.min(99, val || 50));
  var seg = [[25, 0.20], [60, 0.45], [75, 0.64], [85, 0.80], [90, 0.88], [95, 0.97], [99, 1.08]];
  for (var i = 1; i < seg.length; i++) {
    if (v <= seg[i][0]) {
      var x0 = seg[i-1][0], y0 = seg[i-1][1], x1 = seg[i][0], y1 = seg[i][1];
      return y0 + (v - x0) * (y1 - y0) / (x1 - x0);
    }
  }
  return 1.08;
};

// 单个选项的最终命中率
CLUTCH_EVENTS.calcHitRate = function (choice, poolPhase, attrs) {
  if (!choice) return 0.15;
  var attrVal = attrs && attrs[choice.key] != null ? attrs[choice.key] : 80;
  var rate = (CLUTCH_EVENTS.RATE || {})[poolPhase] != null ? CLUTCH_EVENTS.RATE[poolPhase] : 1;
  var mul = choice.hitMul || 1;
  // ★ NBA2.0：比赛选项成功概率上调（×1.12 + 封顶放宽 0.85→0.9，下限 0.15→0.2）
  return Math.max(0.2, Math.min(0.9, choice.base * CLUTCH_EVENTS.hitAF(attrVal) * rate * mul * 1.12));
};

// 触发配置（平衡轮可调）
CLUTCH_EVENTS.CONFIG = {
  maxMargin: 3,        // 终局分差 ≤3 才可能触发
  regularChance: 0.073, // 常规赛每场触发概率（真实分差≤3 占 11.6%，生涯预期约 10 次）
  playoffChance: 0.42,  // 季后赛/附加赛每场触发概率（真实分差≤3 占 11.5%，生涯预期约 8 次）
  rookieMult: 0.25,    // 新秀兜底折扣（无年龄时用）
  // ★ 生涯阶段触发概率：新秀低 → 巅峰高 → 老将中
  stage: {
    rookie:  0.25,    // ≤22 新秀期：事件少，先适应联盟
    young:   0.6,     // 23-25 成长期
    peak:    1.2,     // 26-31 巅峰：主角时刻最多
    prime:   0.9,     // 32-34 维持期
    veteran: 0.6      // 35+ 老将：经验仍在，但戏份回落
  }
};

// 生涯阶段因子：新秀低 → 巅峰高 → 老将中（可配置，见 CONFIG.stage）
CLUTCH_EVENTS.stageFactor = function (age) {
  var cfg = (CLUTCH_EVENTS.CONFIG || {}).stage || {};
  if (age == null) return 1;
  if (age <= 22) return cfg.rookie != null ? cfg.rookie : 0.25;
  if (age <= 25) return cfg.young != null ? cfg.young : 0.6;
  if (age <= 31) return cfg.peak != null ? cfg.peak : 1.2;
  if (age <= 34) return cfg.prime != null ? cfg.prime : 0.9;
  return cfg.veteran != null ? cfg.veteran : 0.6;
};

// 触发判定：比分接近 + 概率（按生涯阶段逐步推进，新秀低/巅峰高/老将中）
CLUTCH_EVENTS.shouldTrigger = function (result, isPlayoff) {
  if (!result) return false;
  var cfg = CLUTCH_EVENTS.CONFIG || {};
  var margin = Math.abs((result.scoreA || 0) - (result.scoreB || 0));
  if (margin > (cfg.maxMargin || 3)) return false;
  // ★ NBA2.0：比赛选项触发概率上调（常规 4.2%→8%，季后赛 25%→35%）
  var chance = isPlayoff ? (cfg.playoffChance || 0.35) : (cfg.regularChance || 0.08);
  try {
    var age = STATE && STATE.career && STATE.career.currentAge;
    if (age == null && STATE && STATE.career && STATE.career.seasonCount === 1) age = 21;
    if (age != null) chance *= CLUTCH_EVENTS.stageFactor(age);
    else if (STATE && STATE.career && STATE.career.seasonCount === 1) chance *= (cfg.rookieMult || 0.25);
  } catch (e) {}
  return Math.random() < chance;
};

// 基础结果应用：命中→落后翻盘/平局绝杀/领先锁定；未命中→维持原模拟结果。
// （完整的士气/球迷/媒体等状态联动放到“结算”阶段做）
CLUTCH_EVENTS.applyClutchResult = function (result, hit, eventId, text, key) {
  if (!result) return result;
  var evs = result.keyEvents || (result.keyEvents = []);
  var diff = (result.scoreA || 0) - (result.scoreB || 0); // A=玩家队
  if (hit) {
    var is3 = key === 'threePT';
    if (diff < 0) {
      var need = -diff;
      if ((is3 && need === 3) || (!is3 && need === 2)) {
        // ★ 命中追平 → 进加时：补齐 ot 标记与加时节比分
        result.scoreA = result.scoreB; // 常规时间打平
        result.ot = (result.ot || 0) + 1;
        var aOT = 8 + Math.floor(Math.random() * 6); // 8-13
        var bOT = 6 + Math.floor(Math.random() * 5); // 6-10
        var winOT = Math.random() < 0.75; // 主角光环：进加时后约 75% 拿下
        var fa = winOT ? Math.max(aOT, bOT + 1) : Math.min(aOT, Math.max(0, bOT - 1));
        result.scoreA += fa;
        result.scoreB += bOT;
        result.won = winOT;
        if (result.qScoresA) result.qScoresA.push(fa);
        if (result.qScoresB) result.qScoresB.push(bOT);
        evs.push('⚡ 关键时刻命中，扳平比分进加时！');
      } else if (need === 1 || (is3 && need === 2)) {
        // 反超绝杀
        result.scoreA = result.scoreB + 1;
        result.won = true;
        evs.push('⚡ 关键时刻命中，反超绝杀！');
      } else {
        // 命中但分值不够（落后 3 分只进两分）：比分更新，但时间走完仍输
        result.scoreA = (result.scoreA || 0) + (is3 ? 3 : 2);
        evs.push('💔 关键时刻命中' + (is3 ? '三分' : '两分') + '，但还差一分——时间走完，功亏一篑');
      }
    } else if (diff === 0) {
      // 平局命中 → 绝杀
      result.scoreA = result.scoreB + 1 + (Math.random() < 0.5 ? 1 : 0);
      result.won = true;
      evs.push('⚡ 关键时刻命中，压哨绝杀！');
    } else {
      // 领先命中 → 锁定胜局
      result.scoreA = (result.scoreA || 0) + 2;
      result.won = true;
      evs.push('⚡ 关键时刻命中，锁定胜局！');
    }
  } else {
    // ★ 未命中被逆转：原本领先且分差 ≤3 时，小概率被对手反绝杀（输球 + 媒体压力/争议）
    var _rev = false;
    if (diff > 0 && diff <= 3 && Math.random() < 0.25) {
      _rev = true;
      result.won = false;
      result.scoreB = (result.scoreA || 0) + 1;
      evs.push('💔 关键时刻失手，被对手反绝杀');
    } else {
      evs.push(result && result.won ? '💔 关键时刻失手，但球队守住了胜利' : '💔 关键时刻失手，时间走完惜败');
    }
    result._clutch = { hit: false, eventId: eventId || '', rate: result._clutchRate || 0, reversed: _rev };
    return result;
  }
  result._clutch = { hit: !!hit, eventId: eventId || '', rate: result._clutchRate || 0 };
  return result;
};

// ============================================================
// 阶段命中率配置：最终命中率 = clamp(base × 属性系数 × RATE[来源池] × (hitMul||1), 0.15, 0.85)
//   regular —— 常规赛 0.95 / playin —— 附加赛 1.05 / playoff —— 普通季后赛 1.1 / game7 —— 抢七 1.15
// ============================================================
CLUTCH_EVENTS.RATE = {
  regular: 0.95,
  playin: 1.05,
  playoff: 1.1,
  game7: 1.15
};

// 抽选辅助：按 阶段 + 位置 + 攻防 过滤，返回 { phase, event }
//   phase —— 请求阶段（regular / playin / playoff / game7）
//   event —— 事件数据；playoff 池带 gameTag（g1_4/g5/g6/any）
// 季后赛先判定 gameNum：G7 → game7 池；G1-6 → playoff 池并按 gameTag 过滤
CLUTCH_EVENTS.pick = function (phase, pos, side, excludeIds, gameTag) {
  var sides = side === "any" ? ["offense", "defense"] : [side];
  var full = [];
  for (var s = 0; s < sides.length; s++) {
    var arr = ((CLUTCH_EVENTS[phase] || {})[pos] || {})[sides[s]] || [];
    for (var i = 0; i < arr.length; i++) full.push(arr[i]);
  }
  var list = full;
  // 普通季后赛按 G 档过滤（g1_4 / g5 / g6 / any）
  if (phase === "playoff" && gameTag && full.length) {
    var tagged = [];
    for (var t = 0; t < full.length; t++) {
      var tg = full[t].gameTag || "any";
      if (tg === "any" || tg === gameTag) tagged.push(full[t]);
      else if (gameTag === "g6w" && tg === "g6") tagged.push(full[t]);
      else if (gameTag === "g6s" && tg === "g6") tagged.push(full[t]);
    }
    if (tagged.length) list = tagged;
  }
  // 空池回退 regular（未填充阶段不抽空）
  if (!list.length) {
    list = [];
    for (var s2 = 0; s2 < sides.length; s2++) {
      var fb = ((CLUTCH_EVENTS.regular || {})[pos] || {})[sides[s2]] || [];
      for (var k = 0; k < fb.length; k++) list.push(fb[k]);
    }
  }
  // 生涯内不重复：排除已触发；当前候选池全部用完 → null（调用方重置）
  if (excludeIds && excludeIds.length) {
    var excl = {};
    for (var x = 0; x < excludeIds.length; x++) excl[excludeIds[x]] = true;
    var filt = [];
    for (var y = 0; y < list.length; y++) if (!excl[list[y].id]) filt.push(list[y]);
    if (filt.length) list = filt;
    else return null;
  }
  if (!list.length) return null;
  var idx = Math.floor(Math.random() * list.length);
  return { phase: phase, event: list[idx] };
};
